<?php
// Restauration ponctuelle de la fiche de Ludovic (supprimée par erreur). À retirer après usage.
declare(strict_types=1);
require_once __DIR__ . '/lib.php';
header('Content-Type: application/json; charset=utf-8');
if (!is_admin() || $_SERVER['REQUEST_METHOD'] !== 'POST' || !hash_equals(csrf_token(), (string)($_POST['csrf'] ?? ''))) { http_response_code(403); echo '{"ok":false}'; exit; }
$d = json_decode(base64_decode(''), true);
$pdo = db();
$e = $d['employe'];
$st = $pdo->prepare('SELECT COUNT(*) FROM employes WHERE id = ? OR pin = ? OR token = ?');
$st->execute([$e['id'], $e['pin'], $e['token']]);
if ((int)$st->fetchColumn() > 0) { echo json_encode(['ok' => false, 'msg' => 'déjà présent']); exit; }
$pdo->beginTransaction();
$cols = array_keys($e);
$pdo->prepare('INSERT INTO employes (' . implode(',', $cols) . ') VALUES (' . implode(',', array_fill(0, count($cols), '?')) . ')')->execute(array_values($e));
foreach ($d['planning'] as $r) $pdo->prepare('INSERT INTO planning (employe_id,etab,jour,debut,fin,motif,note,preset) VALUES (?,?,?,?,?,?,?,?)')->execute(array_values($r));
foreach ($d['pointages'] as $r) $pdo->prepare('INSERT INTO pointages (employe_id,etab,debut,fin,manuel) VALUES (?,?,?,?,?)')->execute(array_values($r));
foreach ($d['indispos'] as $r) $pdo->prepare('INSERT INTO indispos (employe_id,jour,note,created_at) VALUES (?,?,?,?)')->execute(array_values($r));
$pdo->commit();
echo json_encode(['ok' => true, 'planning' => count($d['planning']), 'pointages' => count($d['pointages'])]);
